#!/usr/bin/env python3
"""Append the sixth manually reviewed full-answer batch (ANS-151 through ANS-175)."""
from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; PATH=ROOT/'content'/'answer-layers.json'; DATE='2026-08-15'
def L(i,t,q,s,m,a,tr,f):return {'id':f'ANS-{i:03d}','topic':t,'question':q,'shortAnswer':s,'modelAnswer':m,'assumptions':a,'traps':tr,'followUps':f,'reviewedOn':DATE,'status':'reviewed-full-v1'}
B=[
L(151,'Detection and Decision Theory','What is a false alarm?','A false alarm is a decision that declares a target or event when the defined truth condition is absent; its rate depends on threshold, noise/interference statistics, search volume, and validation.','A detector maps data to a decision using a statistic and threshold. Noise, clutter, interference, model mismatch, multiple comparisons, or artifacts can cross that threshold without a true target. Lowering threshold often improves detection probability while increasing false alarms, so performance should be reported with ROC or precision–recall context, base rate, test set, and operating conditions. A false alarm is not necessarily instrument failure or dishonest data; it is an expected decision error to quantify and manage.', ['Truth labels and decision window defined','Representative noise/background distribution available'],['Reporting false-alarm probability without a trial definition','Optimizing threshold on the same data used for final validation'],['False alarm versus miss?','How threshold trades errors?','What is ROC?','Why base rate matters?','How test under drift?']),
L(152,'Systems Engineering','What is systems thinking?','Systems thinking treats performance and risk as outcomes of interacting requirements, interfaces, feedback, environments, people, and lifecycle stages rather than isolated components.','I would start from stakeholder need and measurable system requirements, then decompose functions while preserving interface, mass, power, thermal, data, timing, safety, and reliability budgets. A locally optimal component can degrade the whole through coupling, common-cause failure, or lifecycle cost. Models, trade studies, configuration control, verification, validation, operations, and feedback from anomalies keep the system coherent. The phrase is useful only when tied to a concrete boundary, interfaces, and decision evidence.', ['System boundary and lifecycle stated','Requirements and interfaces traceable'],['Using “holistic” without a measurable model','Optimizing a subsystem while ignoring interfaces'],['Give an interface failure.','Verification versus validation?','What is requirement traceability?','How handle trade-off?','What is common cause?']),
L(153,'Aerospace Qualification','What is the difference between a prototype and a flight-ready component?','A prototype demonstrates a bounded concept; a flight-ready component must satisfy controlled requirements, interfaces, manufacturing, qualification/acceptance, reliability, documentation, and mission-environment evidence.','A benchtop prototype may prove physical feasibility under convenient conditions with manual operation and non-flight parts. Flight readiness additionally requires baselined requirements, margins, configuration and parts/material control, workmanship, software/firmware control, EMC, thermal-vacuum, vibration/shock and other relevant tests, calibration stability, failure analysis, traceability, and acceptance of the delivered unit. Qualification and acceptance strategies depend on programme standards. A successful demonstration is evidence, not automatic certification.', ['Mission environment and governing standards defined','Configuration under test representative of delivered hardware'],['Calling one environmental test flight qualification','Ignoring manufacturing repeatability and documentation'],['Qualification versus acceptance?','What is engineering model?','How set margins?','What is configuration control?','Which test first?']),
L(154,'Data Analysis','What would a residual plot tell you?','Residuals show data minus model versus order or predictors, revealing bias, curvature, changing variance, correlation, outliers, drift, and regime failure hidden by a headline fit.','I would define residual sign and inspect them against fitted value, independent variable, time/order, and relevant conditions. Random-looking residuals with scale consistent with the uncertainty model support—but do not prove—the model. Structure can indicate missing physics, wrong functional form, heteroscedasticity, correlation, calibration drift, saturation, or processing artifacts. Standardized residuals and independent validation help, while fitting until residuals look good on the same data risks overfitting.', ['Model predicts the measured observable','Uncertainty and dependence model specified'],['Reading residuals only as measurement error','Using R² instead of checking structure'],['What is heteroscedasticity?','Why plot versus time?','What is standardized residual?','How detect autocorrelation?','What next model test?']),
L(155,'Project Translation','What is the gap between laboratory result and device?','The gap includes requirements, repeatability, scale, interfaces, environment, lifetime, manufacturability, calibration, safety, cost, and qualification—not merely improving one measured property.','A laboratory sample establishes a property under a stated preparation and measurement. A device must deliver a function with defined sensitivity, selectivity, stability, power, geometry, packaging, contacts, thermal behavior, control electronics, calibration, and failure criteria. Batch variation, ageing, contamination, environmental loads, production yield, standards, and lifecycle support must be tested. I would identify the dominant uncertainty and build the smallest representative prototype that connects the material property to a device-level requirement.', ['Actual material property and intended function identified','Device operating environment and interfaces defined'],['Calling a promising material plot a device demonstration','Ignoring packaging and calibration'],['Which requirement first?','What prototype?','How test lifetime?','What baseline competitor?','What would stop development?']),
L(156,'Research Integrity','How do you document an experiment?','Use a contemporaneous, traceable record of objective, identifiers, configuration, procedure, calibration, raw-data paths, deviations, environment, analysis version, results, uncertainty, and next decision.','The notebook or controlled record should let another qualified person reconstruct what was intended and what actually happened. I would record sample/batch IDs, instrument and software versions, settings, standards, timestamps, operator, safety authorization, file checksums or paths, and unexpected events before interpretation is polished. Analysis should preserve raw data, code, parameters, exclusions, and figure provenance. Corrections remain visible and dated; a clean final report does not replace the primary record.', ['Institutional data and safety policy followed','Identifiers and clocks/files are controlled'],['Back-filling only successful conditions later','Overwriting raw data or deleting deviations'],['What belongs before a run?','How record correction?','Why software version?','What is chain of custody?','How make analysis reproducible?']),
L(157,'Research Integrity','How do you avoid overclaiming a result?','Match each sentence to what the measurement is physically sensitive to, state uncertainty and alternatives, separate correlation from causation, and use calibrated language for evidence strength.','I would decompose a conclusion into structure, composition, morphology, property, mechanism, and application clauses and ask which calibrated evidence supports each. Controls, detection limits, representative sampling, model assumptions, residuals, repeats, and complementary techniques set the boundary. “Consistent with” is not “proves,” absence of detection is not absence without sensitivity, and a possible application is not device readiness. I would actively state what remains unknown and what observation would falsify the interpretation.', ['Scientific claim and evidence chain explicit','Raw data and uncertainty available'],['Using novelty language to replace evidence','Treating agreement of correlated methods as independent proof'],['What would falsify claim?','How report nondetection?','Correlation versus causation?','What is detection limit?','How word tentative result?']),
L(158,'Launch Vehicle Physics','Why are cryogenic stages useful?','Cryogenic propellants can provide high effective exhaust velocity and specific impulse, especially for upper stages, but demand low-temperature storage, insulation, feed, ignition, and operational complexity.','Hydrogen–oxygen combustion can produce high specific impulse because of high energy release and low exhaust molecular mass, helping upper-stage delta-v and payload performance. That benefit trades against low propellant density, large tanks, boil-off, heat leak, turbomachinery, start/restart, material compatibility, sealing, ground handling, and reliability. “Cryogenic” describes storage temperature, not automatically superior performance; mission stage, thrust, volume, cost, and operations determine suitability.', ['Public conceptual propulsion discussion','Specific propellant pair and stage context stated'],['Saying cryogenic means colder exhaust or universally greater thrust','Ignoring low density and boil-off'],['Why upper stage?','Specific impulse meaning?','Why insulation?','What is boil-off?','Compare solid/liquid conceptually.']),
L(159,'Remote Sensing','What are spatial and spectral resolution?','Spatial resolution describes ground/detail scale represented or separable; spectral resolution describes the width and placement of wavelength bands—both depend on system response, not one marketing number.','Spatial sampling such as GSD is not automatically optical resolution: aperture, MTF, atmosphere, motion, pointing, detector sampling, processing, and SNR matter. Spectral resolution concerns the instrument line shape or band width and ability to distinguish spectral features; more/narrower bands reduce photons per band and increase calibration/data demands. Radiometric and temporal resolution are separate dimensions. Every resolution statement needs wavelength, geometry, criterion, and processing level.', ['Imaging geometry and product level specified','Resolution distinguished from sampling'],['Equating pixel size with resolved detail','Saying more bands are always better'],['What is GSD?','What is MTF?','Radiometric resolution?','How SNR trades spectral width?','How validate resolution?']),
L(160,'Calibration','Why is calibration necessary?','Calibration relates instrument indication to reference quantities with uncertainty, exposing offset, sensitivity, nonlinearity, drift, and environmental dependence needed for defensible measurements.','An uncalibrated output may be repeatable yet biased or expressed only in arbitrary units. I would define the measurand and range, use a suitable traceable reference, apply multiple points and repeats, inspect residuals and hysteresis, validate independent points, and record conditions. Calibration does not remove every error or prove selectivity; it provides a relation and uncertainty over a validated domain with recheck criteria.', ['Reference uncertainty and traceability suitable','Instrument configuration and environment controlled'],['Calling one zero adjustment full calibration','Extrapolating beyond calibrated range'],['Calibration versus validation?','Why multiple points?','What is traceability?','How detect drift?','When recalibrate?']),
L(161,'Spacecraft Operations','What is telemetry, tracking and command?','Telemetry reports spacecraft state/data to ground, tracking estimates trajectory or related observables, and command sends authorized instructions; together TT&C supports safe operation and mission control.','Telemetry includes health, status, events, and payload/engineering data with encoding, timing, units, calibration, and quality flags. Tracking can use range, Doppler, angle, navigation signals, or other observations with orbit determination. Commanding requires authentication, validation, sequencing, constraints, acknowledgment, and contingency procedures. Communication link, ground network, onboard data handling, time synchronization, and safe-mode design are interfaces; public conceptual answers should not speculate about protected protocols.', ['Specific mission architecture and public-domain scope','Reference frames/time and data definitions controlled'],['Calling telemetry only science data','Treating command as an unverified direct actuator action'],['What is ranging?','Why time synchronization?','What if link lost?','How commands verified?','TT&C versus payload downlink?']),
L(162,'Satellite Communications','What limits a satellite link as propagation distance increases?','Free-space spreading reduces received power roughly as 1/R² under ideal far-field conditions; antenna gain, frequency, polarization, atmosphere, pointing, bandwidth, noise, hardware losses, and coding set actual link margin.','Friis relates received and transmitted power using gains and wavelength over range for aligned far-field antennas in free space. Increasing range raises path loss in dB, but detectability depends on energy per bit or carrier-to-noise, receiver noise temperature, bandwidth, implementation loss, modulation/coding, interference, rain/atmosphere, and pointing. A link budget sums gains and losses with margins and availability; it is not only transmitted power or distance.', ['Far-field free-space baseline before additional losses','Frequency, polarization, bandwidth, and noise defined'],['Calling path loss energy disappearance','Ignoring antenna aperture/frequency and noise'],['Write Friis relation.','Why dB budget?','How rain matters?','What is E_b/N_0?','Why pointing margin?']),
L(163,'Antennas','What determines an antenna’s directionality?','Directionality comes from the spatial phase and amplitude distribution of radiating currents over an electrical aperture, shaped by geometry, wavelength, array phasing, platform, and environment.','Far-field contributions interfere constructively in some directions and destructively in others. A larger effective aperture in wavelengths can support a narrower main beam, while illumination trades beamwidth against sidelobes. Arrays steer through relative phase but face grating lobes, coupling, bandwidth, calibration, and scan loss. Directionality is not gain: gain also includes efficiency, and neither creates power. Pattern measurement requires polarization, range, alignment, and calibration.', ['Far-field radiation pattern at a stated frequency','Current distribution and polarization defined'],['Saying every antenna is highly directional','Confusing gain with amplification'],['Gain versus directivity?','Why sidelobes?','How array steers?','What are grating lobes?','How measure pattern?']),
L(164,'Communication Systems','What is a link budget?','A link budget is a traceable accounting of transmit power, gains, propagation and hardware losses, received noise, required performance, and margin under stated conditions.','I would choose a reference plane and add terms consistently in linear or dB units: transmitter output, feeder loss, antenna gain, path/atmospheric/polarization/pointing losses, receive gain/loss, and received carrier. Then I would calculate noise from temperature and bandwidth, include implementation and coding requirements, and compare against required C/N, SNR, or E_b/N_0 with availability and margin. Best-case arithmetic without uncertainty, fading, interference, and ageing is not a design budget.', ['Frequency, geometry, bandwidth and performance criterion stated','All gains/losses use consistent reference and units'],['Mixing dB and dBm or double-counting gain','Reporting margin without availability/environment'],['Why reference plane?','What sets noise power?','C/N versus E_b/N_0?','How include rain?','How validate budget?']),
L(165,'Space Environment and Electronics','How does radiation affect electronics?','Radiation can deposit transient charge, accumulate ionizing dose, displace lattice atoms, and trigger single-event effects; susceptibility depends on particle spectrum, device, bias, geometry, shielding, and mission.','Total ionizing dose can shift thresholds and increase leakage; displacement damage degrades materials and optoelectronic devices; single particles can cause transient, upset, latch-up, burnout, or other events. Mitigation can include part/process selection, shielding analysis, redundancy, error detection/correction, current limiting, reset/safe mode, layout, and testing. Radiation tolerance is system- and environment-specific, and operational limits must come from qualified mission assurance—not a generic shielding claim.', ['Public conceptual environment and device class defined','Mission spectrum/fluence and operating condition specified'],['Calling all effects cumulative dose','Assuming more shielding always improves every particle environment'],['TID versus displacement?','What is SEU?','Why latch-up dangerous?','How test parts?','What is system mitigation?']),
L(166,'Space Safety','What is space debris risk?','Debris can collide at high relative speed, damaging spacecraft or creating further fragments; risk combines encounter probability, object uncertainty, vulnerability, mission phase, and response capability.','Space surveillance observations support conjunction assessment through orbit estimates and covariance. A warning is not certainty: screening thresholds, propagation/model error, maneuverability, tracking updates, and false alarms matter. Mitigation includes design-for-demise or passivation, shielding for small particles, collision-avoidance decision processes, post-mission disposal, and responsible operations under current rules. I would avoid quoting a current conjunction or regulatory requirement from memory.', ['Public safety-level discussion','Current regulations and conjunction data checked officially'],['Equating probability with guaranteed collision','Assuming every alert should trigger a maneuver'],['Why relative speed high?','What is covariance?','How shielding helps?','What is passivation?','How decide maneuver?']),
L(167,'Space Weather','How does solar activity affect spacecraft?','Solar activity changes radiation, plasma, ultraviolet/X-ray output, and geomagnetic conditions, affecting charging, electronics, drag, communication/navigation, sensors, and power.','Flares alter electromagnetic radiation quickly; energetic particles and solar-wind disturbances arrive on different timescales and can drive geomagnetic storms. Consequences can include single-event effects, dose, surface/internal charging, ionospheric propagation errors, increased upper-atmosphere density and drag, sensor background, and solar-array degradation. Effects depend on orbit, shielding, orientation, technology, and operations. Forecasts and alerts are probabilistic and must come from current official services.', ['Event type, orbit and spacecraft technology specified','Current operational data obtained from official services'],['Calling every flare a geomagnetic storm at Earth','Using one index as universal spacecraft risk'],['Flare versus CME?','Why LEO drag changes?','How charging occurs?','Impact on GNSS?','Operational mitigation?']),
L(168,'Nuclear Structure','What determines nuclear stability?','Nuclear stability reflects strong-force binding, Coulomb repulsion, neutron–proton balance, pairing, shell structure, and whether energetically/quantum-allowed decay channels exist.','The semi-empirical mass formula explains broad volume, surface, Coulomb, asymmetry, and pairing trends, while shell closures create additional stability. A nucleus can be energetically able to decay yet long-lived because barriers, angular momentum, parity, phase space, and weak/strong matrix elements suppress the rate. Binding energy per nucleon alone does not predict every decay. Stability should be assessed from consistent masses, Q values, conservation laws, and evaluated nuclear data.', ['Consistent atomic/nuclear mass convention','Ground or specified nuclear state'],['Using B/A alone to predict decay','Calling every positive Q process fast'],['Why neutron excess grows?','What are magic numbers?','Pairing effect?','Q value meaning?','Why alpha barriers matter?']),
L(169,'Nuclear Reactions','What conservation laws govern a reaction?','Nuclear reactions conserve total energy–momentum, electric charge, baryon/nucleon number in ordinary nuclear bookkeeping, and angular momentum; parity and other quantum numbers follow the relevant interaction.','I would write a complete initial and final state including photons, leptons, recoil, and excitation, then apply four-momentum and charge conservation. Nucleon number is useful for ordinary reactions, while beta decay converts neutron/proton and includes leptons. Angular momentum coupling and parity can suppress channels even with positive Q. Thresholds in the laboratory include recoil and momentum conservation. Exact masses and levels should come from evaluated data.', ['Reaction and interaction type identified','Closed initial/final bookkeeping with consistent masses'],['Checking energy only and forgetting momentum/recoil','Conserving proton and neutron number separately in beta decay'],['How calculate Q?','Why threshold exceeds −Q?','Angular momentum selection?','What about neutrino?','When parity not conserved?']),
L(170,'Nuclear Reactions','What is a threshold energy?','Threshold energy is the minimum projectile kinetic energy in a chosen frame for an endothermic reaction to satisfy energy and momentum conservation; in a fixed-target lab it generally exceeds −Q because products must recoil.','At threshold the final particles have no relative kinetic energy in the centre-of-mass frame, but the centre of mass moves in the laboratory. Invariant-mass conservation gives the exact relativistic threshold; nonrelativistic formulas depend on projectile/target/product masses. A positive-Q exothermic reaction may have no kinematic threshold yet still face Coulomb, angular-momentum, or cross-section suppression. “Threshold” can also mean a detector/electronics setting, so context matters.', ['Specified reaction and reference frame','Ground/excited product masses defined'],['Setting lab threshold equal to −Q universally','Assuming no kinematic threshold means large reaction rate'],['Derive recoil reason.','Lab versus CM?','Positive Q case?','Coulomb barrier?','Detector threshold difference?']),
L(171,'Radiation Physics','Compare alpha, beta, gamma, and neutron radiation.','Alpha and beta are charged particles, gamma is electromagnetic radiation, and neutrons are neutral hadrons; their interactions, penetration, ionization patterns, detection, and shielding depend strongly on energy and material.','Alpha particles lose energy densely and usually have short range; beta particles scatter and ionize and can produce bremsstrahlung; gamma rays interact through photoelectric, Compton, and pair processes by energy/material; neutrons scatter from nuclei and may be captured, producing secondary radiation. None has one universal range or shield. Dose and hazard depend on spectrum, geometry, internal/external exposure, and biological context. Real controls require qualified radiation-protection analysis.', ['Radiation energy/spectrum and material specified','Conceptual comparison, not shielding design'],['Ranking hazard by penetration alone','Giving one shielding material for every energy and geometry'],['Why alpha high LET?','Beta bremsstrahlung?','Gamma interaction regimes?','How neutrons detected?','Internal versus external hazard?']),
L(172,'Radiation Physics','What is attenuation?','Attenuation is reduction of a defined radiation or wave quantity through absorption, scattering, geometry, or other loss; the exponential law applies only under stated homogeneous narrow-beam conditions.','For uncollided monoenergetic photons in a uniform absorber, I=I₀e^(−μx), where μ depends on energy and material. A real detector may also receive scattered buildup, and broad spectra change shape as components attenuate differently. Geometry, source size, secondary radiation, detector response, and background matter. Attenuation is not necessarily energy destruction; scattering can redirect energy, and neutron or charged-particle transport needs different models.', ['Defined measured quantity and geometry','Homogeneous medium and interaction regime specified'],['Applying one μ to broad spectra without qualification','Calling attenuation absorption only'],['What is half-value layer?','Why buildup?','Mass attenuation coefficient?','How energy changes μ?','When inverse-square also matters?']),
L(173,'Radiation Dosimetry','What is absorbed dose?','Absorbed dose is mean energy imparted by ionizing radiation per unit mass, measured in gray, J/kg; it is distinct from activity, fluence, counts, and equivalent/effective dose.','Dose is defined for a material and volume under specified irradiation. Converting a detector reading or source activity to absorbed dose requires a calibrated response, spectrum, geometry, transport, material, and time model. Equivalent dose applies radiation weighting and effective dose additionally applies tissue weighting for protection purposes. A generic absorbed dose does not by itself predict an individual biological outcome, and facility decisions belong to qualified dosimetry and procedures.', ['Material, mass/volume, and irradiation field specified','Calibrated dosimetry model'],['Equating activity or count rate with gray','Using absorbed dose and effective dose interchangeably'],['Unit of gray?','Dose versus kerma?','Equivalent dose?','How detector calibrated?','Why geometry matters?']),
L(174,'Radiation Protection','How do time, distance, and shielding reduce dose?','For an external field, reducing time lowers accumulated exposure, increasing distance can reduce fluence by geometry, and suitable shielding attenuates or changes the field—but every application depends on source, spectrum, geometry, and procedure.','Time control reduces integrated exposure rate times duration when conditions are stable. Distance from an ideal point source in open geometry gives an inverse-square trend, which can fail for extended sources, scattering, or near field. Shielding must match radiation type and energy and account for secondary radiation, buildup, gaps, activation, heat, and handling. These are ALARA concepts, not instructions to improvise: authorized surveys, calculations, and facility procedures control real work.', ['External-exposure conceptual scenario','Authorized radiation-protection programme'],['Applying inverse square to every geometry','Adding arbitrary material without secondary-radiation analysis'],['When inverse square fails?','Why shielding differs?','What is buildup?','How monitor dose?','What does ALARA mean?']),
L(175,'Radiation Instrumentation','How would you calibrate a radiation detector?','Use authorized reference fields or sources and traceable standards to relate indication to radiation quantity/energy across the intended range, geometry, rate, and environment with uncertainty.','I would first define whether the detector measures counts, spectrum, dose-related quantity, or contamination response. Under approved procedures, I would establish background and stability, use suitable traceable references at controlled geometry and energies, check energy/channel and efficiency or response as applicable, test linearity, dead time, repeatability, and environmental dependence, and validate independent points. Calibration factors are configuration- and spectrum-dependent; source handling and acceptance belong to authorized personnel.', ['Authorized facility, source, and procedure','Reference uncertainty and detector configuration known'],['Using one check source for every energy and geometry','Treating calibration as removal of dead time/background'],['Energy versus efficiency calibration?','How subtract background?','What is dead time?','Why geometry fixed?','When recalibrate?'])]
def main():
 d=json.loads(PATH.read_text());base=[x for x in d['layers'] if int(x['id'].split('-')[1])<151];later=[x for x in d['layers'] if int(x['id'].split('-')[1])>175];assert len(base)==150;assert len(B)==25;d['layers']=sorted(base+B+later,key=lambda x:int(x['id'].split('-')[1]));assert len({x['id'] for x in d['layers']})==175+len(later);PATH.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(f"Wrote answer batch 6; total reviewed layers: {len(d['layers'])}")
if __name__=='__main__':main()
